import { DOM } from "@anikitenko/fdo-sdk";
import { renderDashboard } from "./features/dashboard/render";
import { renderJsonWorkspace } from "./features/json-workspace/render";
import { renderCategoryWorkspace } from "./features/category-workspace/render";
import { renderLibrary } from "./features/library/render";
import { renderSpace } from "./features/space/render";
import { CATEGORY_KEYS } from "./features/category/types";
import "./styles.css";

const SHELL_BASE_CLASSES = [
  "go11",
  "tool-workbench",
  "dashboard",
  "library",
  "json-workspace",
  "category-workspace",
  "workspace",
  "panel",
  "shell",
];

export function render(): string {
  const dom = new DOM();
  const shellClassName = dom.createClassFromStyle({
    display: "flex",
    flexDirection: "column",
    minHeight: "100vh",
    fontFamily: "'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
    fontSize: "14px",
    color: "#e0e0e0",
    backgroundColor: "#1a1a2e",
    padding: "16px",
    gap: "16px",
  });

  const children = [
    renderDashboard("dashboard"),
    renderLibrary("library"),
    renderJsonWorkspace("json-workspace", "json-result"),
    ...CATEGORY_KEYS.map((key) =>
      renderCategoryWorkspace("category-workspace", "category-result")
    ),
    renderSpace(),
  ];

  const shell = dom.createElement("div", {
    className: [shellClassName, ...SHELL_BASE_CLASSES].join(" "),
    "data-role": "tool-workbench",
  }, ...children);

  return dom.renderHTML(shell);
}

