import type { CategoryKey, CategoryOption } from "../category/types";
import { CATEGORY_META } from "../category/types";

function renderSelectInput(options: CategoryOption[]): string {
  if (options.length === 0) {
    return "";
  }

  const optionTags = options
    .map((opt) => `<option value="${opt.value}">${opt.label}</option>`)
    .join("");

  return `<select class="workspace-select" data-role="tool-category-select">${optionTags}</select>`;
}

function renderInputControl(key: CategoryKey): string {
  const meta = CATEGORY_META[key];

  if (meta.selectOptions.length > 0) {
    return [
      `<div class="workspace-input-row">`,
      `<label class="workspace-label">Input</label>`,
      `<textarea class="workspace-input" data-role="tool-category-input" rows="6" placeholder="${meta.description}" spellcheck="false"></textarea>`,
      renderSelectInput(meta.selectOptions),
      `</div>`,
    ].join("");
  }

  return [
    `<div class="workspace-input-row">`,
    `<label class="workspace-label">Input</label>`,
    `<textarea class="workspace-input" data-role="tool-category-input" rows="8" placeholder="${meta.description}" spellcheck="false"></textarea>`,
    `</div>`,
  ].join("");
}

export function renderCategoryWorkspace(
  workspaceClass: string,
  resultClass: string
): string {
  const keys = Object.keys(CATEGORY_META) as CategoryKey[];

  const sections = keys
    .map((key) => {
      const meta = CATEGORY_META[key];
      const id = `category-workspace-${key}`;

      return [
        `<section class="${workspaceClass}" id="${id}" data-role="tool-category-workspace" data-tool-category="${key}" data-state="closed">`,
        `<div class="workspace-back-row">`,
        `<button type="button" class="workspace-back" data-role="tool-category-back">&larr; Back to dashboard</button>`,
        `</div>`,
        `<div class="workspace-header">`,
        `<h2 class="workspace-title">${meta.label}</h2>`,
        `<p class="workspace-subtitle">${meta.description}</p>`,
        `</div>`,
        `<form class="pure-form pure-form-stacked workspace-form">`,
        renderInputControl(key),
        `<div class="workspace-action-row">`,
        `<button type="button" class="pure-button pure-button-primary workspace-action" data-role="tool-category-action">Run ${meta.label}</button>`,
        `</div>`,
        `</form>`,
        `<div class="workspace-divider"></div>`,
        `<div class="workspace-result">`,
        `<label class="workspace-label">Result</label>`,
        `<pre class="${resultClass} workspace-result" data-role="tool-category-result" data-state="idle"><span class="workspace-ready">Ready &mdash; result will appear here.</span></pre>`,
        `</div>`,
        `</section>`,
      ].join("\n  ");
    })
    .join("\n  ");

  return sections;
}
